import ipaddress
import re

IP_PATTERN = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")

def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    allowed = set(allowed_ips)
    seen: set[str] = set()
    unauthorized: list[str] = []

    with open(log_path, encoding="utf-8") as log:
        for line in log:
            for ip in IP_PATTERN.findall(line):
                try:
                    ipaddress.ip_address(ip)
                except ValueError:
                    continue

                if ip not in allowed and ip not in seen:
                    seen.add(ip)
                    unauthorized.append(ip)

    return unauthorized
